  private void speak(String rpcId,JSONObject input)throws Exception{String text=required(input,"text",3500);if(text.trim().isEmpty())throw new Exception("这条消息还没有可朗读的文字。");if(!ttsReady)throw new Exception("这台设备的系统朗读尚未就绪，请安装或启用中文TTS声音。");String name=input.optString("name","角色的声音.wav");String utterance=input.optString("speechId",UUID.randomUUID().toString());identifier(utterance);File file=new File(getCacheDir(),"tts-"+utterance+".wav");TtsCall call=new TtsCall(rpcId,file,name);runOnUiThread(()->{if(tts!=null)tts.stop();for(TtsCall previous:ttsCalls.values()){clearTts(previous.file);reply(previous.rpcId,false,null,"这句先不念啦。");}ttsCalls.clear();ttsCalls.put(utterance,call);int status=tts.synthesizeToFile(text,new Bundle(),file,utterance);if(status!=TextToSpeech.SUCCESS){ttsCalls.remove(utterance);clearTts(file);reply(rpcId,false,null,"系统朗读没有开始，请检查中文声音设置。");}});timer.schedule(()->{TtsCall pending=ttsCalls.remove(utterance);if(pending!=null){runOnUiThread(()->{if(tts!=null)tts.stop();clearTts(file);});reply(rpcId,false,null,"系统朗读等待过久，请稍后再试。");}},45,TimeUnit.SECONDS);}
  @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);boolean allowed=grants.length>0;for(int grant:grants)allowed=allowed&&grant==PackageManager.PERMISSION_GRANTED;if(code==51&&audioRequest!=null){PermissionRequest request=audioRequest;audioRequest=null;if(allowed&&trustedPage&&PAGE.equals(web.getUrl()))request.grant(request.getResources());else request.deny();}if(code==53&&proactivePermissionId!=null){String id=proactivePermissionId;proactivePermissionId=null;try{if(allowed)reply(id,true,proactiveEngine().enable(true),null);else reply(id,false,null,"通知权限还没开启，后台问候保持关闭；前台仍能收到问候哦。");}catch(Exception e){reply(id,false,null,friendly(e));}}if(code==52&&nativePermissionId!=null){String id=nativePermissionId;nativePermissionId=null;if(allowed)recognize(id);else reply(id,false,null,"麦克风权限还没开启；你仍然可以打字聊天。");}}
  private ProactiveEngine proactiveEngine()throws Exception{if(proactive==null)throw new Exception("本机后台问候暂时没有准备好，请保留资料后重新打开应用。");return proactive;}
  private void readProactiveIntent(Intent intent){if(proactive!=null&&intent!=null&&ProactiveEngine.OPEN_ACTION.equals(intent.getAction())){String conversation=intent.getStringExtra(ProactiveEngine.EXTRA_CONVERSATION);intent.setAction(null);intent.removeExtra(ProactiveEngine.EXTRA_CONVERSATION);proactive.opened(conversation);try{if(web!=null)emit(new JSONObject().put("type","proactive").put("conversationId",conversation));}catch(Exception ignored){}}}
  @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);readProactiveIntent(intent);}
  @Override protected void onResume(){super.onResume();groupsForeground=true;ProactiveEngine.setForeground(true);try{emit(new JSONObject().put("type","app-foreground").put("foreground",true));}catch(Exception ignored){}readProactiveIntent(getIntent());}
  @Override protected void onPause(){groupsForeground=false;for(HttpCall call:calls.values())if(call.foregroundOnly){call.cancelled.set(true);if(call.connection!=null)call.connection.disconnect();}ProactiveEngine.setForeground(false);try{emit(new JSONObject().put("type","app-foreground").put("foreground",false));}catch(Exception ignored){}super.onPause();}
  @Override public void onBackPressed(){if(web!=null&&trustedPage)new AlertDialog.Builder(this).setTitle("先回到桌面吗？").setMessage("聊天和草稿会保存在这台设备上。点对点连接会断开。").setNegativeButton("继续聊天",null).setPositiveButton("保存后退出",(d,w)->web.evaluateJavascript("window.__ohwhaleClose&&window.__ohwhaleClose()",null)).show();else super.onBackPressed();}
  @Override protected void onDestroy(){trustedPage=false;for(HttpCall call:calls.values()){call.cancelled.set(true);if(call.connection!=null)call.connection.disconnect();}if(audioRequest!=null){audioRequest.deny();audioRequest=null;}if(imageChooser!=null){imageChooser.onReceiveValue(null);imageChooser=null;}if(tts!=null){tts.stop();tts.shutdown();}if(web!=null){web.removeJavascriptInterface("OhWhaleNative");web.destroy();}workers.shutdownNow();httpWorkers.shutdownNow();timer.shutdownNow();super.onDestroy();}
